```rust
use std::future::Future;
use std::pin::Pin;

// Boxes and pins the future to return it
pub fn process_data() -> Pin<Box<dyn Future<Output = ()>>> {
    Box::pin(async {
        println!("Hello");
    })
}
```

fix:
Use `impl Future` to let the compiler perform static dispatch and compute the exact state machine size at compile-time, zero-cost.
```rust
use std::future::Future;

pub fn process_data() -> impl Future<Output = ()> {
    async {
        println!("Hello");
    }
}
```
